response:
以下是将Python代码转换为C++的完整实现，使用C++11标准并保持原有功能：

```cpp
#include <iostream>
#include <fstream>
#include <vector>
#include <string>
#include <sstream>
#include <algorithm>
#include <cctype>
#include <stdexcept>
#include <unordered_map>
#include <set>
#include <locale>

class TextProcessor {
public:
    explicit TextProcessor(const std::string& input) : input(input) {}

    void processText() {
        try {
            if (input.empty()) {
                throw std::runtime_error("Input text is empty.");
            }
            // 1. 标点符号替换
            for (char& c : input) {
                if (ispunct(c)) {
                    c = ' ';
                }
            }
            // 2. 分词
            tokenize();
            // 3. 去除停用词
            removeStopWords();
            // 4. 转为小写
            toLowercase();
        } catch (const std::exception& e) {
            std::cerr << "Error: " << e.what() << std::endl;
            throw;
        }
    }

    std::vector<std::string> getTokens() const {
        return tokens;
    }

private:
    std::string input;
    std::vector<std::string> tokens;
    std::set<std::string> stopWords = {
        "the", "and", "is", "in", "to", "of", "a", "an", "on", "at", "for", "by", "with"
    };

    void tokenize() {
        std::istringstream iss(input);
        std::string token;
        while (iss >> token) {
            tokens.push_back(token);
        }
    }

    void removeStopWords() {
        tokens.erase(std::remove_if(tokens.begin(), tokens.end(),
            [&stopWords](const std::string& word) {
                return stopWords.find(word) != stopWords.end();
            }), tokens.end());
    }

    void toLowercase() {
        for (auto& word : tokens) {
            for (char& c : word) {
                c = std::tolower(c);
            }
        }
    }
};

class TextAnalyzer {
public:
    explicit TextAnalyzer(const TextProcessor& processor) : processor(processor) {}

    void analyzeText() {
        try {
            if (processor.tokens.empty()) {
                throw std::runtime_error("No tokens to analyze.");
            }
            calculateWordFrequency();
            calculateTextStatistics();
        } catch (const std::exception& e) {
            std::cerr << "Analysis error: " << e.what() << std::endl;
            throw;
        }
    }

    std::unordered_map<std::string, int> getWordFrequency() const {
        return wordFrequency;
    }

    struct TextStatistics {
        size_t totalWords;
        double averageWordLength;
        double averageSentenceLength;
    };

    TextStatistics getTextStatistics() const {
        return stats;
    }

private:
    const TextProcessor& processor;
    std::unordered_map<std::string, int> wordFrequency;

    void calculateWordFrequency() {
        for (const auto& word : processor.tokens) {
            wordFrequency[word]++;
        }
    }

    void calculateTextStatistics() {
        TextStatistics stats;
        stats.totalWords = processor.tokens.size();
        // 计算平均词长
        double totalChars = 0.0;
        for (const auto& word : processor.tokens) {
            totalChars += word.length();
        }
        stats.averageWordLength = totalChars / stats.totalWords;

        // 简化处理：假设每行是一个句子
        std::istringstream iss(processor.input);
        std::string line;
        int sentenceCount = 0;
        while (std::getline(iss, line)) {
            ++sentenceCount;
        }
        stats.averageSentenceLength = stats.totalWords / static_cast<double>(sentenceCount);
        this->stats = stats;
    }
};

int main() {
    std::string inputText;
    std::cout << "Enter input text: ";
    std::getline(std::cin, inputText);

    try {
        TextProcessor processor(inputText);
        processor.processText();
        TextAnalyzer analyzer(processor);
        analyzer.analyzeText();

        // 输出结果
        std::cout << "\nWord Frequency:\n";
        for (const auto& pair : analyzer.getWordFrequency()) {
            std::cout << pair.first << ": " << pair.second << "\n";
        }

        auto stats = analyzer.getTextStatistics();
        std::cout << "\nText Statistics:\n";
        std::cout << "Total Words: " << stats.totalWords << "\n";
        std::cout << "Avg Word Length: " << stats.averageWordLength << "\n";
        std::cout << "Avg Sentence Length: " << stats.averageSentenceLength << "\n";
    } catch (const std::exception& e) {
        std::cerr << "Program error: " << e.what() << std::endl;
        return 1;
    }

    return 0;
}
```

**代码逻辑概述：**
1. 创建`TextProcessor`类处理文本：替换标点、分词、去除停用词、转小写
2. 创建`TextAnalyzer`类分析文本：计算词频和文本统计信息
3. 主函数获取用户输入，执行处理和分析流程
4. 输出词频统计和文本分析结果

**关键知识点：**
- C++11智能指针未使用（为简化代码）
- 异常处理机制
- STL容器和算法应用
- 字符串处理函数
- 标准输入/输出操作

**优化建议：**
1. 可添加智能指针管理动态对象
2. 增加单元测试验证功能
3. 文件操作可支持多行输入
4. 停用词表可外部配置

**常见错误：**
- 字符处理时未考虑多字节字符集
- 异常处理不完整
- 浮点数精度问题

以下是添加了详细注释的完整C++代码，每个功能模块和关键步骤都有详细解释：

```cpp
#include <iostream>
#include <fstream>
#include <vector>
#include <string>
#include <sstream>
#include <algorithm>
#include <cctype>
#include <stdexcept>
#include <unordered_map>
#include <set>
#include <locale>

/**
 * @brief 文本处理器类，负责处理输入文本（标点替换、分词、去停用词、小写转换）
 */
class TextProcessor {
public:
    /**
     * @brief 构造函数，接收输入文本
     * @param input 输入文本字符串
     */
    explicit TextProcessor(const std::string& input) : input(input) {}

    /**
     * @brief 处理文本的主方法
     * 1. 检查输入是否为空
     * 2. 替换标点符号为空格
     * 3. 分词
     * 4. 去除停用词
     * 5. 转为小写
     */
    void processText() {
        try {
            if (input.empty()) {
                throw std::runtime_error("输入文本为空");
            }
            // 1. 替换文本中的所有标点符号为空格
            for (char& c : input) {
                if (ispunct(c)) {  // 检查字符是否为标点符号
                    c = ' ';  // 替换为空格
                }
            }
            // 2. 分词处理
            tokenize();
            // 3. 去除停用词
            removeStopWords();
            // 4. 转为小写
            toLowercase();
        } catch (const std::exception& e) {
            std::cerr << "处理文本时出错: " << e.what() << std::endl;
            throw;  // 重新抛出异常，以便调用者处理
        }
    }

    /**
     * @brief 获取处理后的词列表
     * @return 处理后的词列表
     */
    const std::vector<std::string>& getTokens() const {
        return tokens;
    }

private:
    std::string input;  // 原始输入文本
    std::vector<std::string> tokens;  // 处理后的词列表

    // 停用词集合（常用无意义词汇）
    std::set<std::string> stopWords = {
        "the", "and", "is", "in", "to", "of", "a", "an", "on", "at", "for", "by", "with"
    };

    /**
     * @brief 将文本分割成单词
     * 使用字符串流从处理后的文本中提取单词
     */
    void tokenize() {
        std::istringstream iss(input);
        std::string token;
        while (iss >> token) {  // 从输入中提取单词
            tokens.push_back(token);  // 将单词添加到词列表
        }
    }

    /**
     * @brief 从词列表中移除停用词
     * 使用std::remove_if算法移除停用词
     */
    void removeStopWords() {
        // 从tokens中移除所有停用词
        tokens.erase(std::remove_if(tokens.begin(), tokens.end(),
            [&stopWords](const std::string& word) {  // lambda表达式，检查单词是否为停用词
                return stopWords.find(word) != stopWords.end();  // 如果单词在停用词集合中找到，则移除
            }), tokens.end());
    }

    /**
     * @brief 将所有单词转为小写
     * 遍历每个单词，将其中的每个字符转为小写
     */
    void toLowercase() {
        for (auto& word : tokens) {  // 遍历每个单词
            for (char& c : word) {  // 遍历单词中的每个字符
                c = std::tolower(c);  // 将字符转为小写
            }
        }
    }
};

/**
 * @brief 文本分析器类，基于TextProcessor的处理结果进行文本分析
 */
class TextAnalyzer {
public:
    /**
     * @brief 构造函数，接收TextProcessor对象的引用
     * @param processor TextProcessor对象的引用
     */
    explicit TextAnalyzer(const TextProcessor& processor) : processor(processor) {}

    /**
     * @brief 执行文本分析
     * 1. 检查是否有词可供分析
     * 2. 计算词频
     * 3. 计算文本统计信息
     */
    void analyzeText() {
        try {
            if (processor.tokens.empty()) {  // 检查是否有词可供分析
                throw std::runtime_error("没有词可供分析");
            }
            calculateWordFrequency();  // 计算词频
            calculateTextStatistics();  // 计算文本统计信息
        } catch (const std::exception& e) {
            std::cerr << "分析文本时出错: " << e.what() << std::endl;
            throw;
        }
    }

    /**
     * @brief 获取词频统计结果
     * @return 词频统计的哈希映射
     */
    const std::unordered_map<std::string, int>& getWordFrequency() const {
        return wordFrequency;
    }

    /**
     * @brief 文本统计信息结构体
     */
    struct TextStatistics {
        size_t totalWords;                  // 总词数
        double averageWordLength;           // 平均词长
        double averageSentenceLength;       // 平均句子长度
    };

    /**
     * @brief 获取文本统计信息
     * @return 包含文本统计信息的结构体
     */
    TextStatistics getTextStatistics() const {
        return stats;
    }

private:
    const TextProcessor& processor;      // 对TextProcessor的引用
    std::unordered_map<std::string, int> wordFrequency;  // 词频统计

    // 文本统计信息（仅在analyzeText方法中有效）
    TextStatistics stats;

    /**
     * @brief 计算词频
     * 遍历所有词并统计每个词出现的次数
     */
    void calculateWordFrequency() {
        for (const auto& word : processor.tokens) {  // 遍历所有词
            wordFrequency[word]++;  // 词频计数
        }
    }

    /**
     * @brief 计算文本统计信息
     * 包括总词数、平均词长和平均句子长度
     */
    void calculateTextStatistics() {
        // 初始化统计信息
        TextStatistics stats;
        stats.totalWords = processor.tokens.size();  // 总词数

        // 计算平均词长
        double totalChars = 0.0;  // 总字符数
        for (const auto& word : processor.tokens) {  // 遍历所有词
            totalChars += word.length();  // 累加字符数
        }
        stats.averageWordLength = totalChars / stats.totalWords;  // 计算平均词长

        // 计算平均句子长度
        // 注意：这里简化处理，假设每行文本为一个句子
        std::istringstream iss(processor.input);  // 创建字符串流
        std::string line;
        int sentenceCount = 0;  // 句子数量计数

        // 统计行数（假设每行是一个句子）
        while (std::getline(iss, line)) {  // 按行读取
            ++sentenceCount;  // 句子计数增加
        }

        // 计算平均句子长度（词数/句子数）
        stats.averageSentenceLength = static_cast<double>(stats.totalWords) / sentenceCount;

        this->stats = stats;  // 存储计算结果
    }
};

/**
 * @brief 主函数，程序入口点
 * @return 程序执行状态
 */
int main() {
    std::string inputText;
    std::cout << "请输入文本内容（输入完成后按Ctrl+D或Ctrl+Z结束）: ";
    std::getline(std::cin, inputText);  // 从标准输入读取整行文本

    try {
        // 创建文本处理器并处理文本
        TextProcessor processor(inputText);
        processor.processText();

        // 创建文本分析器并进行分析
        TextAnalyzer analyzer(processor);
        analyzer.analyzeText();

        // 输出词频统计结果
        std::cout << "\n词频统计结果:\n";
        for (const auto& pair : analyzer.getWordFrequency()) {  // 遍历词频映射
            std::cout << pair.first << ": " << pair.second << "\n";  // 输出词和词频
        }

        // 输出文本统计信息
        auto stats = analyzer.getTextStatistics();
        std::cout << "\n文本统计信息:\n";
        std::cout << "总词数: " << stats.totalWords << "\n";
        std::cout << "平均词长: " << stats.averageWordLength << "\n";
        std::cout << "平均句子长度: " << stats.averageSentenceLength << "\n";
    } catch (const std::exception& e) {
        std::cerr << "程序执行出错: " << e.what() << std::endl;
        return 1;  // 返回非零值表示程序异常终止
    }

    return 0;  // 返回零表示程序正常结束
}
```

**代码逻辑概述：**
1. **TextProcessor类**：负责文本预处理，包括标点替换、分词、去停用词和小写转换
2. **TextAnalyzer类**：基于预处理后的文本进行分析，计算词频和文本统计信息
3. **main函数**：程序入口，获取用户输入，创建处理器和分析器，输出结果

**关键知识点详解：**
1. **异常处理**：使用try-catch块处理可能的错误，提高程序健壮性
2. **标准库应用**：
   - `<sstream>`：用于字符串流操作，方便分词
   - `<unordered_map>`：哈希表实现，提供快速查找和插入
   - `<set>`：有序集合，用于存储停用词
3. **算法应用**：
   - `std::remove_if`：从容器中移除满足特定条件的元素
   - `std::for_each`：对容器元素应用函数
4. **字符串处理**：
   - `std::ispunct`：检查字符是否为标点符号
   - `std::tolower`：将字符转为小写
5. **输入/输出**：
   - `std::getline`：从输入流中读取整行

**优化建议：**
1. 可添加命令行参数支持，实现文件读取功能
2. 停用词表可配置化，支持用户自定义
3. 可添加多线程支持，提高处理效率
4. 文本统计部分可进一步优化，更精确地识别句子边界

**常见错误及解决：**
1. **编译错误**：确保C++11或更高版本编译器
2. **运行时错误**：输入为空时未处理
3. **浮点精度问题**：使用double类型计算统计数据

