# C++ Data Cleaning and Preprocessing

Here's a complete C++ implementation of the data cleaning and preprocessing functionality from the Python code:

```cpp
#include <iostream>
#include <fstream>
#include <sstream>
#include <vector>
#include <algorithm>
#include <cctype>
#include <iomanip>
#include <set>
#include <map>
#include <cmath>
#include <regex>
#include <ctime>
#include <string>
#include <cstdio>
#include <cstdlib>
#include <unordered_map>
#include <stdexcept>

using namespace std;

// Data structure to represent a cleaned dataset
struct DataCleaner {
    // Input and output file paths
    string input_file;
    string output_file;

    // Data storage
    vector<vector<string>> rows;
    vector<string> headers;

    // Column information
    map<string, string> column_types;
    map<string, bool> is_numerical;
    map<string, bool> is_date;

    // Constructor
    DataCleaner(const string& input, const string& output) {
        input_file = input;
        output_file = output;
    }

    // Load data from CSV file
    bool load_data() {
        ifstream file(input_file);
        if (!file.is_open()) {
            cerr << "Error: File " << input_file << " not found!" << endl;
            return false;
        }

        string line;
        getline(file, line); // Read header

        // Parse header
        stringstream ss(line);
        string header;
        headers.clear();
        while (getline(ss, header, ',')) {
            headers.push_back(header);
            column_types[header] = "unknown";
        }

        // Read data rows
        rows.clear();
        while (getline(file, line)) {
            if (line.empty()) continue;

            stringstream ss(line);
            vector<string> row;
            string cell;
            while (getline(ss, cell, ',')) {
                row.push_back(cell);
            }
            rows.push_back(row);
        }

        // Infer column types
        infer_column_types();

        cout << "Data loaded successfully!" << endl;
        return true;
    }

    // Infer data types for each column
    void infer_column_types() {
        for (int i = 0; i < headers.size(); i++) {
            string col_name = headers[i];
            bool is_num = true;
            bool is_date = false;

            // Check if column is numerical
            for (const auto& row : rows) {
                if (!row[i].empty()) {
                    // Check if it's not a number
                    if (row[i][0] == '-' && row[i].size() > 1) {
                        // Negative numbers
                        for (int j = 1; j < row[i].size(); j++) {
                            if (!isdigit(row[i][j])) {
                                is_num = false;
                                break;
                            }
                        }
                    } else {
                        for (int j = 0; j < row[i].size(); j++) {
                            if (!isdigit(row[i][j])) {
                                is_num = false;
                                break;
                            }
                        }
                    }

                    // Check for date format
                    if (is_num) {
                        // Check if it might be a date
                        if (row[i].size() == 10 && row[i][4] == '-' && row[i][7] == '-') {
                            is_date = true;
                        }
                    }
                }
            }

            if (is_num) {
                column_types[col_name] = "numerical";
                is_numerical[col_name] = true;
            } else {
                column_types[col_name] = "categorical";
                is_numerical[col_name] = false;

                if (is_date) {
                    column_types[col_name] = "date";
                    is_date[col_name] = true;
                }
            }
        }
    }

    // Remove duplicate rows
    int remove_duplicates() {
        set<vector<string>> seen;
        vector<vector<string>> unique_rows;

        for (const auto& row : rows) {
            if (seen.find(row) == seen.end()) {
                seen.insert(row);
                unique_rows.push_back(row);
            }
        }

        rows = unique_rows;
        int duplicates_removed = rows.size() - unique_rows.size();
        cout << "Duplicates removed: " << duplicates_removed << " rows" << endl;
        return duplicates_removed;
    }

    // Handle missing values
    void handle_missing_values(const string& strategy, bool numerical_only = true) {
        int missing_before = 0;
        for (const auto& row : rows) {
            for (const auto& cell : row) {
                if (cell.empty()) {
                    missing_before++;
                }
            }
        }

        if (strategy == "drop") {
            vector<vector<string>> new_rows;
            for (const auto& row : rows) {
                bool has_missing = false;
                for (const auto& cell : row) {
                    if (cell.empty()) {
                        has_missing = true;
                        break;
                    }
                }
                if (!has_missing) {
                    new_rows.push_back(row);
                }
            }
            rows = new_rows;
        } else {
            for (int i = 0; i < headers.size(); i++) {
                string col_name = headers[i];
                if (numerical_only && !is_numerical[col_name]) continue;

                if (strategy == "mean") {
                    // Calculate mean for numerical columns
                    if (is_numerical[col_name]) {
                        double sum = 0.0;
                        int count = 0;
                        for (const auto& row : rows) {
                            if (!row[i].empty()) {
                                try {
                                    double value = stod(row[i]);
                                    sum += value;
                                    count++;
                                } catch (...) {
                                    // If conversion fails, skip this cell
                                    continue;
                                }
                            }
                        }

                        if (count > 0) {
                            double mean = sum / count;
                            for (auto& row : rows) {
                                if (row[i].empty()) {
                                    row[i] = to_string(mean);
                                }
                            }
                        }
                    }
                } else if (strategy == "mode") {
                    // Calculate mode for categorical columns
                    if (!is_numerical[col_name]) {
                        map<string, int> frequency;
                        for (const auto& row : rows) {
                            if (!row[i].empty()) {
                                frequency[row[i]]++;
                            }
                        }

                        string mode;
                        int max_freq = 0;
                        for (const auto& entry : frequency) {
                            if (entry.second > max_freq) {
                                max_freq = entry.second;
                                mode = entry.first;
                            }
                        }

                        for (auto& row : rows) {
                            if (row[i].empty()) {
                                row[i] = mode;
                            }
                        }
                    }
                }
            }
        }

        int missing_after = 0;
        for (const auto& row : rows) {
            for (const auto& cell : row) {
                if (cell.empty()) {
                    missing_after++;
                }
            }
        }

        cout << "Missing values handled: " << missing_before - missing_after << " values" << endl;
    }

    // Standardize dates
    void standardize_dates(const vector<string>& date_columns = {}) {
        if (date_columns.empty()) {
            // Auto-detect date columns
            for (int i = 0; i < headers.size(); i++) {
                if (is_date[headers[i]]) {
                    date_columns.push_back(headers[i]);
                }
            }
        }

        cout << "Found " << date_columns.size() << " potential date columns" << endl;

        for (const string& col_name : date_columns) {
            int index = -1;
            for (int i = 0; i < headers.size(); i++) {
                if (headers[i] == col_name) {
                    index = i;
                    break;
                }
            }

            if (index == -1) {
                cout << "Warning: Column " << col_name << " not found!" << endl;
                continue;
            }

            bool converted = false;
            vector<string> formats = {"%Y-%m-%d", "%Y/%m/%d", "%m/%d/%Y", "%Y-%m-%d %H:%M:%S"};

            for (const string& fmt : formats) {
                try {
                    // Convert to datetime using specified format
                    for (auto& row : rows) {
                        if (!row[index].empty()) {
                            // Remove time part if present
                            string date_str = row[index];
                            size_t pos = date_str.find(" ");
                            if (pos != string::npos) {
                                date_str = date_str.substr(0, pos);
                            }

                            // Convert to datetime
                            time_t t;
                            struct tm tm_buf = {0};
                            memset(&tm_buf, 0, sizeof(tm_buf));

                            // Try parsing with the given format
                            char* ptr;
                            strptime(date_str.c_str(), fmt.c_str(), &tm_buf);

                            t = mktime(&tm_buf);
                            if (t != (time_t)-1) {
                                // Convert to standard format
                                string date_str_std = ctime(&t);
                                // Remove newline character
                                if (!date_str_std.empty()) {
                                    date_str_std.pop_back();
                                }
                                row[index] = date_str_std;
                                converted = true;
                            }
                        }
                    }

                    if (converted) {
                        cout << "Standardized date column: " << col_name << endl;
                        break;
                    }
                } catch (...) {
                    continue;
                }
            }

            if (!converted) {
                // Try parsing without format specification
                for (auto& row : rows) {
                    if (!row[index].empty()) {
                        try {
                            // Convert to datetime using default parsing
                            string date_str = row[index];
                            size_t pos = date_str.find(" ");
                            if (pos != string::npos) {
                                date_str = date_str.substr(0, pos);
                            }

                            // Parse the date string
                            struct tm tm_buf = {0};
                            memset(&tm_buf, 0, sizeof(tm_buf));

                            if (strptime(date_str.c_str(), NULL, &tm_buf) != NULL) {
                                time_t t = mktime(&tm_buf);
                                if (t != (time_t)-1) {
                                    string date_str_std = ctime(&t);
                                    if (!date_str_std.empty()) {
                                        date_str_std.pop_back();
                                    }
                                    row[index] = date_str_std;
                                    converted = true;
                                }
                            }
                        } catch (...) {
                            // Conversion failed
                        }
                    }
                }

                if (converted) {
                    cout << "Standardized date column: " << col_name << endl;
                }
            }
        }
    }

    // Standardize text data
    void standardize_text(const vector<string>& text_columns = {}) {
        if (text_columns.empty()) {
            // Auto-detect text columns
            for (int i = 0; i < headers.size(); i++) {
                if (!is_numerical[headers[i]] && !is_date[headers[i]]) {
                    text_columns.push_back(headers[i]);
                }
            }
        }

        // First, fill missing values with empty strings
        for (const string& col_name : text_columns) {
            int index = -1;
            for (int i = 0; i < headers.size(); i++) {
                if (headers[i] == col_name) {
                    index = i;
                    break;
                }
            }

            if (index == -1) {
                continue;
            }

            for (auto& row : rows) {
                if (row[index].empty()) {
                    row[index] = "";
                }
            }
        }

        // Then, apply text standardization
        for (const string& col_name : text_columns) {
            int index = -1;
            for (int i = 0; i < headers.size(); i++) {
                if (headers[i] == col_name) {
                    index = i;
                    break;
                }
            }

            if (index == -1) {
                continue;
            }

            for (auto& row : rows) {
                string& s = row[index];
                if (s.empty()) continue;

                // Remove leading/trailing whitespace
                size_t start = s.find_first_not_of(" ");
                size_t end = s.find_last_not_of(" ");
                if (start == string::npos) {
                    s = "";
                } else {
                    s = s.substr(start, end - start + 1);
                }

                // Remove special characters
                string new_s;
                for (char c : s) {
                    if (isalnum(c) || isspace(c)) {
                        new_s += c;
                    }
                }
                s = new_s;

                // Convert to lowercase
                for (char& c : s) {
                    if (isupper(c)) {
                        c = tolower(c);
                    }
                }
            }
        }
    }

    // Save data to CSV file
    bool save_to_csv() {
        ofstream file(output_file);
        if (!file.is_open()) {
            cerr << "Error: Could not create file " << output_file << endl;
            return false;
        }

        // Write header
        for (int i = 0; i < headers.size(); i++) {
            file << headers[i];
            if (i < headers.size() - 1) {
                file << ",";
            }
        }
        file << endl;

        // Write data rows
        for (const auto& row : rows) {
            for (int i = 0; i < row.size(); i++) {
                file << row[i];
                if (i < row.size() - 1) {
                    file << ",";
                }
            }
            file << endl;
        }

        cout << "Data saved to " << output_file << endl;
        return true;
    }
};

int main() {
    // Create data cleaner instance
    DataCleaner cleaner("input.csv", "output.csv");

    // Load data
    if (!cleaner.load_data()) {
        return 1;
    }

    // Remove duplicates
    cleaner.remove_duplicates();

    // Handle missing values (mean strategy for numerical columns)
    cleaner.handle_missing_values("mean");

    // Standardize dates
    cleaner.standardize_dates();

    // Standardize text
    cleaner.standardize_text();

    // Save processed data
    cleaner.save_to_csv();

    return 0;
}
```

## Key Features

1. **Data Loading**: Reads CSV files and infers column types automatically
2. **Duplicate Removal**: Identifies and removes duplicate rows
3. **Missing Value Handling**: Supports mean/mode imputation and row removal
4. **Date Standardization**: Converts dates to a consistent format using multiple parsing strategies
5. **Text Standardization**: Cleans text by removing special characters and normalizing case
6. **Data Persistence**: Saves processed data to a CSV file

## Usage Instructions

1. Save the code to a file (e.g., `data_cleaner.cpp`)
2. Compile it using a C++ compiler:
   ```bash
   g++ -std=c++11 data_cleaner.cpp -o data_cleaner
   ```
3. Create an input CSV file named `input.csv`
4. Run the program:
   ```bash
   ./data_cleaner
   ```
5. The processed data will be saved to `output.csv`

The program automatically detects column types and handles missing values for numerical columns. You can customize the behavior by modifying the parameters in the main function.

