        }

        // Clean product ID
        string cleaned_product_id = removeNonAlphanumeric(record.product_id);
        if (cleaned_product_id.empty()) {
            return nullopt;
        }

        // Clean customer ID
        string cleaned_customer_id = removeNonAlphanumeric(record.customer_id);
        if (cleaned_customer_id.empty()) {
            return nullopt;
        }

        // Clean quantity
        string cleaned_quantity_str = removeNonNumeric(record.quantity_str);
        int cleaned_quantity = 0;
        try {
            cleaned_quantity = stoi(cleaned_quantity_str);
            if (cleaned_quantity <= 0) {
                return nullopt;
            }
        } catch (...) {
            return nullopt;
        }

        // Create cleaned record
        TransactionRecord cleaned_record;
        cleaned_record.date = cleaned_date;
        cleaned_record.amount = cleaned_amount;
        cleaned_record.product_id = cleaned_product_id;
        cleaned_record.customer_id = cleaned_customer_id;
        cleaned_record.quantity = cleaned_quantity;
        cleaned_record.transaction_id = record.transaction_id;
        cleaned_record.timestamp = record.timestamp;
        cleaned_record.store_location = record.store_location;
        cleaned_record.payment_method = record.payment_method;
        cleaned_record.tax_amount = record.tax_amount;
        cleaned_record.discount_amount = record.discount_amount;
        cleaned_record.comments = record.comments;

        return cleaned_record;
    }

    // Clean a list of transaction records
    vector<TransactionRecord> cleanTransactionRecords(const vector<TransactionRecord>& records) {
        vector<TransactionRecord> cleaned_records;

        for (const auto& record : records) {
            auto cleaned = cleanTransactionRecord(record);
            if (cleaned) {
                cleaned_records.push_back(*cleaned);
            }
        }

        // Remove duplicates
        unordered_set<string> seen;
        vector<TransactionRecord> unique_records;

        for (const auto& rec : cleaned_records) {
            if (seen.find(rec.transaction_id) == seen.end()) {
                seen.insert(rec.transaction_id);
                unique_records.push_back(rec);
            }
        }

        return unique_records;
    }

private:
    // Helper function to remove regex patterns
    string removeRegex(const string& input, const regex& pattern) {
        string result = input;
        sregex_iterator it(result.begin(), result.end(), pattern);
        sregex_iterator end;

        while (it != end) {
            result.erase(it.base().position(), it.base().str().length());
            it++;
        }

        return result;
    }

    // Helper function to remove non-alphanumeric characters
    string removeNonAlphanumeric(const string& input) {
        string result;
        for (char c : input) {
            if (isalnum(c) || c == ' ' || c == '_') {
                result += c;
            }
        }
        return result;
    }

    // Helper function to remove extra whitespace
    string removeExtraWhitespace(const string& input) {
        string result;
        bool inWord = false;
        string currentWord;

        for (char c : input) {
            if (isspace(c)) {
                if (!currentWord.empty()) {
                    result += currentWord + " ";
                    currentWord.clear();
                }
            } else {
                currentWord += c;
            }
        }

        if (!currentWord.empty()) {
            result += currentWord;
        }

        return result;
    }

    // Helper function to remove stopwords
    string removeStopwords(const string& input) {
        string result;
        size_t start = 0;
        size_t end = 0;

        while (end <= input.size()) {
            if (end == input.size() || isspace(input[end])) {
                if (end > start) {
                    string word = input.substr(start, end - start);
                    // Convert word to lowercase for comparison
                    transform(word.begin(), word.end(), word.begin(),
                        [](unsigned char c) { return tolower(c); });

                    if (stopwords_.find(word) == stopwords_.end()) {
                        result += word + " ";
                    }
                }
                start = end + 1;
            }
            end++;
        }

        // Remove trailing space
        if (!result.empty() && isspace(result.back())) {
            result.pop_back();
        }

        return result;
    }

    // Helper function to standardize date formats
    string standardizeDate(const string& date_str) {
