        // If all formats fail, try to parse as any date format
        try {
            // This is a placeholder for a more robust date parser
            return date_str;
        } catch (...) {
            return "";
        }
    }

    // Helper function to remove non-numeric characters
    string removeNonNumeric(const string& input) {
        string result;
        for (char c : input) {
            if (isdigit(c)) {
                result += c;
            }
        }
        return result;
    }

