        cleaned_text = removeNonAlphanumeric(cleaned_text);

        // Remove extra whitespace
        cleaned_text = removeExtraWhitespace(cleaned_text);

        // Remove stopwords
        cleaned_text = removeStopwords(cleaned_text);

        // Remove empty strings
        if (cleaned_text.empty()) {
            return nullopt;
        }

        // Only keep message if it has meaningful content (at least 2 words)
        vector<string> words;
        size_t start = 0;
        size_t end = 0;

        while (end <= cleaned_text.size()) {
            if (end == cleaned_text.size() || isspace(cleaned_text[end])) {
                if (end > start) {
                    string word = cleaned_text.substr(start, end - start);
                    if (!word.empty() && word.find_first_not_of("0123456789abcdefghijklmnopqrstuvwxyz") == string::npos) {
                        words.push_back(word);
                    }
                }
                start = end + 1;
            }
            end++;
